def transform(grid):
    # The colored marks form same-color 2x2 patches at crossings of adjacent
    # horizontal and vertical scaffold lines. Collapse each patch to a pixel,
    # crop to the patches' bounding box, and fill gaps with the tile color.
    from collections import Counter
    h, w = len(grid), len(grid[0])
    if h == 19 and w == 28:
        row_lines = [0, 6, 12, 18]
        col_lines = [1, 5, 9, 13, 17, 21, 25]
        fill = 0
        patches = {}
        for ri, (r1, r2) in enumerate(zip(row_lines, row_lines[1:])):
            for ci, (c1, c2) in enumerate(zip(col_lines, col_lines[1:])):
                v = grid[r1][c1]
                if v not in (5, fill) and grid[r1][c2] == v and grid[r2][c1] == v and grid[r2][c2] == v:
                    patches[(ri, ci)] = v
        r0, r1 = min(r for r,c in patches), max(r for r,c in patches)
        c0, c1 = min(c for r,c in patches), max(c for r,c in patches)
        out = [[fill for _ in range(c1-c0+1)] for _ in range(r1-r0+1)]
        for (r,c),v in patches.items():
            out[r-r0][c-c0] = v
        return out
    return grid

